  {t:"Alucinación", en:"Hallucination", d:"Salida falsa pero plausible generada por un FM."},
  {t:"Guardrails", en:"Barreras de protección", d:"Controles que filtran contenido dañino y refuerzan políticas de uso responsable."},
  {t:"Sesgo", en:"Bias", d:"Errores sistemáticos que pueden favorecer o perjudicar a ciertos grupos o resultados."},
  {t:"Varianza", en:"Variance", d:"Sensibilidad del modelo a los datos de entrenamiento; alta varianza = overfitting."},
  {t:"Overfitting", en:"Sobreajuste", d:"El modelo memoriza el entrenamiento y generaliza mal a datos nuevos."},
  {t:"Underfitting", en:"Infraajuste", d:"El modelo es demasiado simple y no captura los patrones de los datos."},
  {t:"Explicabilidad", en:"Explainability", d:"Capacidad de entender por qué un modelo tomó una decisión."},
  {t:"Multimodal", en:"Multimodal", d:"Modelo que procesa/genera múltiples tipos de datos (texto, imagen, audio)."},
  {t:"Modelo de difusión", en:"Diffusion model", d:"Tipo de modelo generativo usado para crear imágenes a partir de ruido."},
  {t:"Inyección de prompts", en:"Prompt injection", d:"Ataque que manipula el prompt para que el modelo ignore sus instrucciones o revele datos."},
  {t:"MLOps", en:"MLOps", d:"Prácticas para desplegar, monitorear y mantener modelos de ML en producción de forma confiable."},
  {t:"ROI", en:"Return on Investment", d:"Métrica de negocio que mide el retorno económico de una inversión en IA."},
  {t:"MCP", en:"Model Context Protocol", d:"Protocolo estándar para conectar agentes de IA con herramientas y datos externos."}
